package net.mandomc.gameplay.mobs;
import java.util.*;import java.util.concurrent.ThreadLocalRandom;import java.util.function.*;
import org.bukkit.*;import org.bukkit.command.ConsoleCommandSender;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.EntityDamageByEntityEvent;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.util.*;import org.bukkit.util.Vector;import org.joml.Quaternionf;import org.joml.Vector3f;
import net.mandomc.commands.RootCommand;import net.mandomc.integrations.models.RancorBone;
/** Ground rupture, foot shock and animated swipe trails. Only the forward rupture owns new damage. */
public final class RancorSlam implements AutoCloseable,Listener {
 public static final String TAG="mandomc_rancor_rubble";
 private enum Mode {LINE,STOMP}
 private static final class Wave {
  final UUID owner;final Location center;final Vector direction;final Mode mode;final int start;final double limit;final Set<UUID> hit=new HashSet<>();int step=1,next;
  Wave(LivingEntity actor,Location center,Vector direction,Mode mode,double limit,int now){owner=actor.getUniqueId();this.center=center;this.direction=direction;this.mode=mode;this.limit=limit;start=next=now;}
 }
 private static final class Trail {final UUID owner;final String side;final int start;Location last;Vector motion=new Vector();Trail(UUID id,String side,int tick){owner=id;this.side=side;start=tick;}}
 private record Fragment(UUID owner,BlockDisplay display,Location floor,int born,float size,float height,float spin){}
 private record Hit(UUID owner,UUID victim){}
 private final JavaPlugin plugin;private final List<Wave> waves=new ArrayList<>();private final List<Fragment> fragments=new ArrayList<>();private final Map<UUID,Trail> trails=new HashMap<>();private final Map<Hit,Vector> lineHits=new HashMap<>();
 private final RancorSlamSettings settings;private final Predicate<Location> allowed;private final Function<Entity,String> type;private final RancorBone bones;private final org.bukkit.scheduler.BukkitTask task;
 public RancorSlam(JavaPlugin plugin,RancorSlamSettings settings,Function<Entity,String> type,Predicate<Location> allowed,RootCommand root) throws ReflectiveOperationException {
  this.plugin=plugin;this.settings=settings;this.allowed=allowed;this.type=type;bones=new RancorBone();
  root.register("rancorslam","mandomc.admin.status",(sender,args)->{if(!(sender instanceof ConsoleCommandSender)||args.length<1||args.length>2)return;try{var actor=actor(args[0]);if(actor==null)return;var target=args.length==2?Bukkit.getEntity(UUID.fromString(args[1])):null;var direction=target instanceof LivingEntity&&target.getWorld()==actor.getWorld()?target.getLocation().toVector().subtract(actor.getLocation().toVector()).setY(0):actor.getLocation().getDirection().setY(0);if(direction.lengthSquared()<0.001)direction=new Vector(0,0,1);direction.normalize();var center=actor.getLocation();var collision=actor.getWorld().rayTraceBlocks(center.clone().add(0,0.8,0),direction,settings.radius(),FluidCollisionMode.NEVER,true);double limit=collision==null?settings.radius():Math.max(0,collision.getHitPosition().distance(center.toVector().add(new Vector(0,0.8,0)))-0.2);start(actor,center,direction,Mode.LINE,limit);}catch(IllegalArgumentException ignored){}},(s,a)->List.of());
  root.register("rancorstomp","mandomc.admin.status",(sender,args)->{if(!(sender instanceof ConsoleCommandSender)||args.length!=2||!Set.of("left","right").contains(args[1]))return;try{var actor=actor(args[0]);if(actor==null)return;var center=bones.position(actor,args[1]+"_foot").orElse(actor.getLocation());center.setY(actor.getY());start(actor,center,new Vector(0,0,1),Mode.STOMP,Math.min(12,settings.radius()));}catch(IllegalArgumentException ignored){}},(s,a)->List.of());
  root.register("rancorswipe","mandomc.admin.status",(sender,args)->{if(!(sender instanceof ConsoleCommandSender)||args.length!=2||!Set.of("left","right").contains(args[1]))return;try{var actor=actor(args[0]);if(actor!=null&&(trails.containsKey(actor.getUniqueId())||trails.size()<8))trails.put(actor.getUniqueId(),new Trail(actor.getUniqueId(),args[1],Bukkit.getCurrentTick()));}catch(IllegalArgumentException ignored){}},(s,a)->List.of());
  Bukkit.getPluginManager().registerEvents(this,plugin);task=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,1,2);
 }
 private LivingEntity actor(String id){var e=Bukkit.getEntity(UUID.fromString(id));return e instanceof LivingEntity actor&&e.isValid()&&!e.isDead()&&"Rancor".equals(type.apply(e))&&allowed.test(e.getLocation())?actor:null;}
 private void start(LivingEntity actor,Location center,Vector direction,Mode mode,double limit){remove(actor.getUniqueId());trails.remove(actor.getUniqueId());if(waves.size()<settings.maxWaves())waves.add(new Wave(actor,center.clone(),direction,mode,limit,Bukkit.getCurrentTick()));}
 private void tick(){int now=Bukkit.getCurrentTick();for(var it=waves.iterator();it.hasNext();){var wave=it.next();var source=Bukkit.getEntity(wave.owner);if(!(source instanceof LivingEntity actor)||!actor.isValid()||actor.isDead()||actor.getWorld()!=wave.center.getWorld()||now-wave.start>Math.ceil(wave.limit/(wave.mode==Mode.LINE?settings.ringStep():3))*settings.ringInterval()+settings.lifetime()){it.remove();removeFragments(wave.owner);continue;}double step=wave.mode==Mode.LINE?settings.ringStep():3;double previous=(wave.step-1)*step;if(now>=wave.next&&previous<wave.limit){double distance=Math.min(wave.limit,wave.step*step);if(wave.mode==Mode.LINE){emitLine(wave,distance,now);hitLine(actor,wave,previous,distance);}else emitStomp(wave,distance,now);wave.step++;wave.next+=settings.ringInterval();}}
  for(var it=fragments.iterator();it.hasNext();){var p=it.next();double t=(now-p.born)/(double)settings.lifetime();if(t>=1||!p.display.isValid()){p.display.remove();it.remove();continue;}p.display.teleport(p.floor.clone().add(0,4*p.height*t*(1-t),0));float scale=p.size*(float)Math.min(1,(1-t)*4);p.display.setTransformation(new Transformation(new Vector3f(-scale/2,0,-scale/2),new Quaternionf().rotateXYZ(p.spin*(float)t,p.spin*(float)t*0.7f,p.spin*(float)t*0.4f),new Vector3f(scale),new Quaternionf()));}
  for(var it=trails.values().iterator();it.hasNext();){var trail=it.next();var e=Bukkit.getEntity(trail.owner);if(!(e instanceof LivingEntity actor)||!e.isValid()||e.isDead()||now-trail.start>24){it.remove();continue;}var point=bones.position(actor,trail.side+"_hand").orElse(null);if(point==null)continue;int age=now-trail.start;if(trail.last!=null&&point.getWorld()==trail.last.getWorld()){var delta=point.toVector().subtract(trail.last.toVector());if(delta.clone().setY(0).lengthSquared()>0.001)trail.motion=delta.clone().setY(0);if(age>=4&&age<=20){int count=Math.max(1,Math.min(8,(int)Math.ceil(delta.length()/0.65)));for(int i=1;i<=count;i++){var at=trail.last.clone().add(delta.clone().multiply(i/(double)count));if(allowed.test(at))at.getWorld().spawnParticle(Particle.SWEEP_ATTACK,at,1,0,0,0,0);}if(age%4<=1&&allowed.test(point))point.getWorld().spawnParticle(Particle.EXPLOSION,point,1,0.1,0.1,0.1,0);}}trail.last=point;}
 }
 private void emitLine(Wave wave,double distance,int now){var side=new Vector(-wave.direction.getZ(),0,wave.direction.getX());for(double width:new double[]{-1.5,-0.75,0,0.75,1.5})fragment(wave,wave.center.clone().add(wave.direction.clone().multiply(distance)).add(side.clone().multiply(width)),now,false);}
 private void emitStomp(Wave wave,double radius,int now){for(int i=0;i<8;i++){double a=2*Math.PI*i/8;fragment(wave,wave.center.clone().add(Math.cos(a)*radius,0,Math.sin(a)*radius),now,true);}}
 private void fragment(Wave wave,Location point,int now,boolean stomp){if(fragments.size()>=settings.maxFragments()||!point.getWorld().isChunkLoaded(point.getBlockX()>>4,point.getBlockZ()>>4)||!allowed.test(point))return;var floor=surface(point);if(floor==null)return;var data=floor.clone().subtract(0,0.05,0).getBlock().getBlockData();var random=ThreadLocalRandom.current();float size=(float)random.nextDouble(stomp?0.55:0.4,stomp?0.95:0.8),height=(float)random.nextDouble(stomp?1.2:0.9,stomp?2.1:1.7),spin=(float)random.nextDouble(-2.5,2.5);
  var display=floor.getWorld().spawn(floor,BlockDisplay.class,e->{e.setPersistent(false);e.setGravity(false);e.setBlock(data);e.addScoreboardTag(TAG);e.addScoreboardTag(stomp?"mandomc_rancor_stomp":"mandomc_rancor_line");e.setViewRange(0.8f);e.setInterpolationDuration(2);e.setTeleportDuration(2);e.setTransformation(new Transformation(new Vector3f(-size/2,0,-size/2),new Quaternionf(),new Vector3f(size),new Quaternionf()));});fragments.add(new Fragment(wave.owner,display,floor,now,size,height,spin));floor.getWorld().spawnParticle(Particle.BLOCK,floor.clone().add(0,0.12,0),stomp?8:5,0.3,0.15,0.3,0.05,data);
 }
 private void hitLine(LivingEntity actor,Wave wave,double previous,double next){for(var p:actor.getWorld().getPlayers()){if(p.isDead()||p.getGameMode()==GameMode.CREATIVE||p.getGameMode()==GameMode.SPECTATOR||wave.hit.contains(p.getUniqueId())||!allowed.test(actor.getLocation())||!allowed.test(p.getLocation()))continue;var delta=p.getLocation().toVector().subtract(wave.center.toVector());double along=delta.dot(wave.direction),side=delta.getX()*(-wave.direction.getZ())+delta.getZ()*wave.direction.getX();if(!RancorLine.hits(along,side,delta.getY(),previous,next))continue;wave.hit.add(p.getUniqueId());var key=new Hit(actor.getUniqueId(),p.getUniqueId());lineHits.put(key,wave.direction.clone());try{p.damage(10,actor);}finally{lineHits.remove(key);}}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void hit(EntityDamageByEntityEvent event){if(!(event.getDamager() instanceof LivingEntity actor)||!(event.getEntity() instanceof Player player)||event.getFinalDamage()<=0||!"Rancor".equals(type.apply(actor)))return;var line=lineHits.get(new Hit(actor.getUniqueId(),player.getUniqueId()));var trail=trails.get(actor.getUniqueId());if(line==null&&(trail==null||Bukkit.getCurrentTick()-trail.start>24))return;Vector direction;double horizontal,vertical;if(line!=null){direction=line.clone();horizontal=1.7;vertical=1.3;}else{direction=trail.motion.clone().setY(0);if(direction.lengthSquared()<0.01){var forward=actor.getLocation().getDirection().setY(0);direction=new Vector(-forward.getZ(),0,forward.getX()).multiply(trail.side.equals("left")?-1:1);}horizontal=1.6;vertical=0.5;}if(direction.lengthSquared()<0.0001)return;var velocity=direction.normalize().multiply(horizontal).setY(vertical);Bukkit.getScheduler().runTask(plugin,()->{if(!event.isCancelled()&&actor.isValid()&&player.isValid()&&!player.isDead()&&actor.getWorld()==player.getWorld()&&allowed.test(actor.getLocation())&&allowed.test(player.getLocation()))player.setVelocity(velocity);});}
 private Location surface(Location point){for(int offset:new int[]{0,-1,1,-2,2,-3,3}){var b=point.getWorld().getBlockAt(point.getBlockX(),point.getBlockY()-1+offset,point.getBlockZ());if(!b.getType().isSolid()||!b.getRelative(0,1,0).isPassable()||b.getState() instanceof org.bukkit.block.TileState)continue;double top=b.getCollisionShape().getBoundingBoxes().stream().mapToDouble(box->box.getMaxY()).max().orElse(0);if(top>0)return new Location(point.getWorld(),point.getX(),b.getY()+top+0.02,point.getZ());}return null;}
 private void removeFragments(UUID id){fragments.removeIf(f->{if(!f.owner.equals(id))return false;f.display.remove();return true;});}
 private void remove(UUID id){waves.removeIf(w->w.owner.equals(id));removeFragments(id);}
 public void close(){task.cancel();HandlerList.unregisterAll(this);fragments.forEach(f->f.display.remove());fragments.clear();waves.clear();trails.clear();lineHits.clear();}
}
